// پاکسازی و نگهداری همه فیلدها
const items = $input.all();
const cleanedItems = [];

items.forEach(item => {
    // اگه آیتم به صورت عجیب ذخیره شده (مثل قبلی)
    if (item.json && typeof item.json === 'object') {
        // بررسی کن ببین فیلدها چطور ذخیره شدن
        const newItem = { json: {} };

        // اگه کلید عجیب "company_name, website_url, ..." وجود داره
        const keys = Object.keys(item.json);
        if (keys.length === 1 && keys[0].includes(',')) {
            // این همون فرمت قبلیه با هدرهای یکجا
            const headers = keys[0].split(',').map(h => h.trim());
            const values = item.json[keys[0]].split(',').map(v => v.trim());

            headers.forEach((header, index) => {
                newItem.json[header] = values[index] || '';
            });
        } else {
            // فرمت عادی - همه فیلدها رو کپی کن
            Object.assign(newItem.json, item.json);
        }

        cleanedItems.push(newItem);
    }
});

console.log(`✅ Cleaned ${cleanedItems.length} items`);
if (cleanedItems.length > 0) {
    console.log('Sample item:', JSON.stringify(cleanedItems[0].json, null, 2));
}

return cleanedItems;

// تبدیل CSV به JSON
const items = $input.all();
const result = [];

items.forEach(item => {
    // استخراج CSV از ورودی
    let csv = '';
    if (item.json?.data) {
        csv = item.json.data;
    } else if (typeof item.json === 'string') {
        csv = item.json;
    } else {
        csv = JSON.stringify(item.json);
    }

    // جدا کردن خطوط
    const lines = csv.split(/\r?\n/).filter(line => line.trim());
    if (lines.length < 2) return;

    // استخراج هدرها از خط اول
    const headers = lines[0].split(',').map(h => h.trim());

    // پردازش ردیف‌ها
    for (let i = 1; i < lines.length; i++) {
        const values = lines[i].split(',').map(v => v.trim());
        const newItem = { json: {} };

        headers.forEach((header, index) => {
            newItem.json[header] = values[index] || '';
        });

        result.push(newItem);
    }
});

console.log(`✅ ${result.length} items created`);
return result;

// پردازش نتایج اسکرپینگ
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // بررسی موفقیت درخواست
  if (data.status === 'success' && data.data) {
    results.push({
      json: {
        company_name: data.company || 'Unknown',
        website_url: data.url,
        scraped_data: data.data,
        scraped_at: new Date().toISOString(),
        service_type: data.service_type || 'general',
        status: 'success'
      }
    });
  } else {
    // ثبت خطا برای بررسی بعدی
    console.error(`❌ Failed to scrape ${data.company || data.url}:`, data.error || 'Unknown error');
    results.push({
      json: {
        company_name: data.company || 'Unknown',
        website_url: data.url,
        scraped_data: null,
        scraped_at: new Date().toISOString(),
        error: data.error || 'Scraping failed',
        status: 'failed'
      }
    });
  }
}

console.log(`✅ Processed ${results.length} scraping results`);
return results;

